INSERT INTO productVariants (productId, printfulVariantId, name, retailPrice, currency, size, color, inStock)
SELECT id, 7005, CONCAT(name, ' - Black / One Size'), 2800, 'USD', 'One Size', 'Black', 1
FROM products WHERE name = 'Hive Mind Cap' ORDER BY id DESC LIMIT 1;

